function commandPalette(){ if(ENH.palette){ paletteClose(); return; } var wrap=document.createElement("div"); wrap.id="palette"; wrap.className="palette-wrap"; wrap.innerHTML='<div class="palette" role="dialog" aria-label="'+attr(tr("Command palette"))+'"><div class="palette-head"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg><input id="paletteInput" placeholder="'+attr(tr("Search ZenCrevia… tasks, people, projects, actions"))+'" autocomplete="off"><kbd>Esc</kbd></div><div class="palette-list" id="paletteList"></div><div class="palette-foot"><span>↑↓ '+tr("navigate")+'</span><span>↵ '+tr("open")+'</span><span>'+esc(shortcutCombo("K"))+' '+tr("close")+'</span></div></div>'; document.body.appendChild(wrap); ENH.palette={sel:0,items:[]}; var inp=wrap.querySelector("#paletteInput"); inp.addEventListener("input",function(){ ENH.palette.sel=0; paletteRender(); }); inp.addEventListener("keydown",function(e){ var p=ENH.palette; if(e.key==="ArrowDown"){ e.preventDefault(); p.sel=Math.min(p.items.length-1,p.sel+1); paletteRender(); } else if(e.key==="ArrowUp"){ e.preventDefault(); p.sel=Math.max(0,p.sel-1); paletteRender(); } else if(e.key==="Enter"){ e.preventDefault(); paletteRun(p.sel); } else if(e.key==="Escape"){ e.preventDefault(); paletteClose(); } }); wrap.addEventListener("mousedown",function(e){ if(e.target===wrap) paletteClose(); }); paletteRender(); setTimeout(function(){ inp.focus(); },10); }
